#ifndef CODEPUPPY_PACKAGE_MANAGER_IPC_H
#define CODEPUPPY_PACKAGE_MANAGER_IPC_H
#include <mach/mach.h>
#include <stddef.h>
static inline void pm_clear(void *bytes, size_t length) { volatile unsigned char *value=bytes; while(length--) *value++=0; }
/* IDs are generated by main (UUID and source offset), never program/argv/env slots. */
typedef struct {
  mach_msg_header_t header;
  char execution[64];
  char node[64];
  char proof[65];
} pm_claim_message;
enum { PM_DELEGATED = 1, PM_FENCED, PM_UNAUTHORIZED, PM_INACTIVE, PM_CONSUMED };
typedef struct {
  mach_msg_header_t header;
  int kind;
  unsigned port;
  char authorization[65];
} pm_grant_message;
#endif
